    MappingSet = apps.get_model("registry", "MappingSet")
    Term = apps.get_model("registry", "Term")

    by_name = dict(RESERVED_PREFIXES)
    namespaces = set(by_name.values())
    used = set(Term.objects.values_list("prefix", flat=True).distinct())
    for curie_map in MappingSet.objects.order_by("created_at").values_list(
        "curie_map", flat=True
    ):
        for name, namespace in (curie_map or {}).items():
            if not isinstance(namespace, str) or name not in used:
                continue
            if name in by_name or namespace in namespaces:
                continue
            by_name[name] = namespace
            namespaces.add(namespace)
    Prefix.objects.bulk_create(
        [Prefix(prefix=name, namespace=ns) for name, ns in by_name.items()],
        ignore_conflicts=True,
    )


